import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import assert from 'node:assert/strict';import {execFileSync} from 'node:child_process';
const root='/home/apnex/taceng/agp',context='/home/apnex/taceng/context-lab';
const checks=JSON.parse(fs.readFileSync(root+'/docs/reviews/admission-diagnostic-correction-handoff-checks.json','utf8'));
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
const id=p=>{const b=fs.readFileSync(p);return {path:p,bytes:b.length,sha256:hash(b)};};
const git=(repo,...args)=>execFileSync('git',['-C',repo,...args],{encoding:'utf8'});
const before=checks.before;const source=fs.readFileSync(before.source.path,'utf8');const delivery=fs.readFileSync(checks.placement.delivery.path,'utf8');
assert.deepEqual(id(before.source.path),before.source);assert.deepEqual(id(before.sourceChecks.path),before.sourceChecks);
const sourceChecks=JSON.parse(fs.readFileSync(before.sourceChecks.path,'utf8'));
const byRef=new Map(checks.linkMap.map(m=>[m.sourceReference,m]));
const rebased=source.replace(/\]\(([^)\s#]+)(#[^)]*)?\)/gu,(whole,ref,fragment='')=>{const m=byRef.get(ref);if(!m)return whole;assert.equal(m.fragment,fragment);assert.equal(path.resolve(path.dirname(before.source.path),ref),m.target);assert.equal(path.resolve(path.dirname(checks.placement.delivery.path),m.deliveryReference),m.target);return ']('+m.deliveryReference+fragment+')';});
assert.equal(delivery,checks.cover+rebased);
let recovered=delivery.slice(checks.cover.length);for(const m of checks.linkMap){const ref=']('+m.deliveryReference+m.fragment+')';assert.equal(recovered.split(ref).length,2);recovered=recovered.replace(ref,']('+m.sourceReference+m.fragment+')');}assert.equal(recovered,source);
assert.deepEqual(id(checks.placement.delivery.path),checks.placement.delivery);
const board=fs.readFileSync(root+'/docs/BOARD.md','utf8'),verification=fs.readFileSync(root+'/docs/VERIFICATION.md','utf8');
let originalBoard=board;for(const [old,replacement] of [...checks.trackingEdits.board].reverse()){if(replacement){assert.equal(originalBoard.split(replacement).length,2);originalBoard=originalBoard.replace(replacement,old);}else{const marker='| Where should the Nexus/OpenCode';assert.equal(originalBoard.split(marker).length,2);originalBoard=originalBoard.replace(marker,old+marker);}}
assert.equal(hash(originalBoard),before.preExistingDirtyFiles.find(p=>p.path.endsWith('/docs/BOARD.md')).sha256);
assert.equal(verification.split(checks.trackingEdits.verificationInsertion).length,2);
const originalVerification=verification.replace(checks.trackingEdits.verificationInsertion,'');
assert.equal(hash(originalVerification),before.preExistingDirtyFiles.find(p=>p.path.endsWith('/docs/VERIFICATION.md')).sha256);
const protectedFiles=[...new Map([...before.preExistingDirtyFiles,...sourceChecks.validation.supplemental.output.preservedFiles,...before.contextDirtyFiles].filter(p=>!['/docs/BOARD.md','/docs/VERIFICATION.md'].some(s=>p.path.endsWith(s))).map(p=>[p.path,p])).values()];
for(const p of protectedFiles)assert.deepEqual(id(p.path),p);
for(const p of before.incoming)assert.deepEqual(id(p.path),p);
assert.deepEqual(fs.readdirSync(context+'/incoming').sort(),[...before.incoming.map(p=>path.basename(p.path)),path.basename(checks.placement.delivery.path)].sort());
assert.equal(git(root,'rev-parse','HEAD').trim(),before.agpHead);assert.equal(git(context,'rev-parse','HEAD').trim(),before.contextHead);assert.equal(git(root,'diff','--cached','--name-only'),before.agpIndex);assert.equal(git(context,'diff','--cached','--name-only'),before.contextIndex);
const dirty=repo=>[...new Set([...git(repo,'diff','--name-only','-z').split('\0'),...git(repo,'ls-files','--others','--exclude-standard','-z').split('\0')].filter(Boolean))].sort();
assert.deepEqual(dirty(root),[...before.preExistingDirtyFiles.map(p=>path.relative(root,p.path)),'docs/reviews/admission-diagnostic-correction-handoff.md','docs/reviews/admission-diagnostic-correction-handoff-checks.json'].sort());
assert.deepEqual(dirty(context),[...before.contextDirtyFiles.map(p=>path.relative(context,p.path)),'incoming/agp-admission-diagnostic-correction-request.md'].sort());
const slug=v=>v.trim().toLowerCase().replace(/<[^>]*>/gu,'').replace(/[\x60*_~]/gu,'').replace(/[.,:;!?()[\]{}'"\\/|<>@#$%^&+=]/gu,'').replace(/\s/gu,'-');
const anchors=t=>{const set=new Set(),seen=new Map();for(const l of t.split(/\r?\n/u)){const m=/^#{1,6}\s+(.+?)\s*$/u.exec(l);if(m){const s=slug(m[1]),n=seen.get(s)||0;seen.set(s,n+1);set.add(n?s+'-'+n:s);}}return set;};
const changed=[checks.placement.delivery.path,root+'/docs/reviews/admission-diagnostic-correction-handoff.md',root+'/docs/BOARD.md',root+'/docs/VERIFICATION.md'];
const links=changed.map(file=>{let count=0;for(const m of fs.readFileSync(file,'utf8').matchAll(/\]\(([^)\s#]*)(#[^)\s]+)?\)/gu)){if(/^(?:https?:|mailto:)/u.test(m[1]))continue;const target=m[1]?path.resolve(path.dirname(file),m[1]):file;assert.ok(fs.existsSync(target),file+' -> '+m[1]);if(m[2]&&target.endsWith('.md'))assert.ok(anchors(fs.readFileSync(target,'utf8')).has(m[2].slice(1)),file+' -> '+m[0]);count++;}return {path:file,localLinks:count,missing:0};});
const tracked=git(root,'ls-files','*.md').split('\n').filter(p=>p&&fs.existsSync(root+'/'+p));
const failures=beforeEdit=>{const result=[];for(const file of tracked){const text=beforeEdit&&file==='docs/BOARD.md'?originalBoard:beforeEdit&&file==='docs/VERIFICATION.md'?originalVerification:fs.readFileSync(root+'/'+file,'utf8');for(const m of text.matchAll(/\]\(([^)\s#]+)(#[^)]*)?\)/gu)){if(/^(?:https?:|mailto:)/u.test(m[1]))continue;const resolved=path.normalize(path.join(path.dirname(root+'/'+file),m[1]));if(!fs.existsSync(resolved))result.push({file,reference:m[1],checkerTarget:resolved,actualTargetExists:fs.existsSync(path.resolve(path.dirname(root+'/'+file),m[1]))});}}return result;};
const baselineFailures=failures(true),currentFailures=failures(false);assert.deepEqual(currentFailures,baselineFailures);assert.equal(currentFailures.length,7);assert.ok(currentFailures.every(f=>f.actualTargetExists&&f.reference.startsWith('/')));
console.log(JSON.stringify({measuredAt:new Date().toISOString(),environment:{node:process.version,platform:process.platform,arch:process.arch},artifacts:changed.map(id),inverseRebaseByteEquality:true,rebasedLinks:checks.linkMap.length,protectedFileCount:protectedFiles.length,protectedFiles,onlyDeclaredTrackingEdits:true,onlyNewIncomingFile:checks.placement.delivery.path,headAndIndexUnchanged:true,dirtyPathSetsAsExpected:true,links,preExistingLinkFailures:currentFailures,newLinkFailures:0,baselineFailureSetEqual:true}));

